// Server only: resolves public share links and builds the data they may see.
// Uses the service role, so every query here is scoped to the one website the
// token resolved to, and returns an allowlist of fields.

import { withoutQuery } from "@/lib/analytics";
import { SCORE_METRICS, TIMING_METRICS } from "@/lib/pagespeed";
import { supabaseAdmin } from "@/lib/supabase";
import { timeframeStart } from "@/lib/timeframe";
import type { PerformanceMetrics, SharedPayload } from "@/types";

// Tokens are generated by the database as 64 lowercase hex characters.
const TOKEN = /^[0-9a-f]{64}$/;

/** The domain segment of a share URL, or null when it is not valid percent-encoding. */
export function decodeDomain(segment: string): string | null {
  try {
    return decodeURIComponent(segment);
  } catch {
    return null;
  }
}

const METRIC_KEYS = [...SCORE_METRICS, ...TIMING_METRICS].map((m) => m.key);

/** Saved PageSpeed results of this exact website row (names aren't unique across accounts). */
async function metricsOf(websiteId: string): Promise<PerformanceMetrics | null> {
  const { data, error } = await supabaseAdmin()
    .from("websites")
    .select(METRIC_KEYS.join(", "))
    .eq("id", websiteId)
    .maybeSingle<Partial<Record<keyof PerformanceMetrics, number | null>>>();
  if (error) throw new Error(error.message);
  if (!data || data.performance == null) return null;
  return Object.fromEntries(METRIC_KEYS.map((key) => [key, Number(data[key] ?? 0)])) as unknown as PerformanceMetrics;
}

/** The website a share link opens, or null for a missing, revoked, malformed or wrong-domain link. */
export async function resolveShare(domain: string, token: string): Promise<{ id: string; name: string } | null> {
  if (!TOKEN.test(token)) return null;
  const admin = supabaseAdmin();
  const { data: link, error } = await admin.from("share_links").select("website_id").eq("token", token).maybeSingle();
  if (error) throw new Error(error.message);
  if (!link) return null;
  const { data: site, error: siteError } = await admin
    .from("websites")
    .select("id, name")
    .eq("id", link.website_id)
    .maybeSingle();
  if (siteError) throw new Error(siteError.message);
  return site && site.name === domain ? site : null;
}

/** The shared view's data for one website: no ids, no custom events, no query strings. */
export async function getSharedPayload(site: { id: string; name: string }, timeframe: string): Promise<SharedPayload> {
  const domain = site.name;
  const admin = supabaseAdmin();
  const since = timeframeStart(timeframe)?.toISOString();
  const tenMinutesAgo = new Date(Date.now() - 10 * 60_000).toISOString();

  let views = admin
    .from("page_views")
    .select("page, created_at, city, region, country, operating_system, device_type, browser_name, client_session_id")
    .eq("domain", domain);
  let visits = admin.from("visits").select("created_at, source").eq("website_id", domain);
  let engagement = admin.from("page_engagement").select("page, client_session_id, engaged_ms, created_at").eq("domain", domain);
  if (since) {
    views = views.gte("created_at", since);
    visits = visits.gte("created_at", since);
    engagement = engagement.gte("created_at", since);
  }
  const active = admin
    .from("page_views")
    .select("id", { count: "exact", head: true })
    .eq("domain", domain)
    .gte("created_at", tenMinutesAgo);

  const [v, s, g, a, metrics] = await Promise.all([
    views,
    visits,
    engagement,
    active,
    metricsOf(site.id).catch((error) => {
      console.error("Shared metrics query failed:", error instanceof Error ? error.message : error);
      return null;
    }),
  ]);
  const error = v.error ?? s.error;
  if (error) throw new Error(error.message);
  if (g.error) console.error("Shared engagement query failed:", g.error.message);
  if (a.error) console.error("Shared active users query failed:", a.error.message);

  // Session ids become per-response labels: enough to group a visit, useless outside this response.
  const labels = new Map<string, string>();
  const label = (id: string | null) => {
    if (!id) return null;
    if (!labels.has(id)) labels.set(id, `s${labels.size + 1}`);
    return labels.get(id)!;
  };

  return {
    domain,
    timeframe,
    pageViews: (v.data ?? []).map(({ client_session_id, ...row }) => ({
      ...row,
      page: withoutQuery(row.page ?? ""),
      client_session_id: label(client_session_id),
    })),
    visits: s.data ?? [],
    engagement: (g.data ?? [])
      .filter((row) => row.client_session_id)
      .map((row) => ({
        page: withoutQuery(row.page ?? ""),
        client_session_id: label(row.client_session_id)!,
        engaged_ms: row.engaged_ms,
        created_at: row.created_at,
      })),
    activeUsers: a.count ?? 0,
    metrics,
  };
}
